function categoryArt(k){if(!Object.hasOwn(CATEGORY_ART,k))throw Error("Unknown category art");return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 320"><rect width="600" height="320" fill="#eaf0f8"/><circle cx="510" cy="55" r="95" fill="#dce7f4"/><circle cx="60" cy="280" r="110" fill="#dce7f4"/><rect x="24" y="24" width="552" height="272" rx="28" fill="none" stroke="#fff" stroke-width="3"/>'+CATEGORY_ART[k]+'</svg>\n';}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}

function publicText(v){return String(v??"").replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,"[contact via LEOGO]").replace(/(?:\+?254|0)[\s.-]?[17](?:[\s.-]?\d){8}\b/g,"[contact via LEOGO]").slice(0,3000);}

function uuid(v){return typeof v==="string"&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);}

function image(r,stage){const buckets={services:"service-provider-public-media",cyber:"cyber-public-media",accommodation:"accommodation-public-media",transport:"transport-public-media",properties:"vacant-house-public-media",sellers:"seller-product-media"};const p=r.image_path;if(stage||r.image_bucket!==buckets[r.kind]||typeof p!=="string"||p.length>600||!/\.(?:jpe?g|png|webp|avif|gif)$/i.test(p)||p.split("/").some(s=>!s||s==="."||s===".."||!/^[A-Za-z0-9_. -]+$/.test(s)))return "";return "https://dzdciuqkqixwutvtfotj.supabase.co/storage/v1/object/public/"+r.image_bucket+"/"+p.split("/").map(encodeURIComponent).join("/");}

function normalize(rows){if(!Array.isArray(rows)||rows.length>10000)throw Error("Invalid business catalogue");const seen=new Set();return rows.map(r=>{if(!r||!Object.hasOwn(GROUPS,r.kind)||!uuid(r.id)||typeof r.title!=="string"||!r.title.trim()||r.title.length>250||seen.has(r.kind+"/"+r.id)||(GROUPS[r.kind].type&&!uuid(r.partner_id)))throw Error("Invalid business listing");seen.add(r.kind+"/"+r.id);return {kind:r.kind,id:r.id,partner_id:r.partner_id,title:publicText(r.title),business:publicText(r.business),description:publicText(r.description),location:publicText(r.location),price_from:typeof r.price_from==="number"&&Number.isFinite(r.price_from)&&r.price_from>0?r.price_from:null,price_to:typeof r.price_to==="number"&&Number.isFinite(r.price_to)&&r.price_to>0?r.price_to:null,pricing_model:String(r.pricing_model??""),unit:publicText(r.unit).slice(0,80),image_bucket:r.image_bucket,image_path:r.image_path};}).sort((a,b)=>(a.kind+a.id).localeCompare(b.kind+b.id));}

function action(r){const group=GROUPS[r.kind];return group.type?"/?partner_type="+encodeURIComponent(group.type)+"&partner_id="+encodeURIComponent(r.partner_id)+"#"+group.anchor:"/#"+group.anchor;}

function price(r){const money=n=>"KSh "+n.toLocaleString("en-KE",{maximumFractionDigits:2});if(/quote|custom|negotiat/i.test(r.pricing_model)||!r.price_from)return r.kind==="sellers"?"View current product prices":"Request a quote / check price";const range=r.price_to&&r.price_to>r.price_from?money(r.price_from)+" – "+money(r.price_to):((r.pricing_model==="from"&&r.kind!=="properties")?"From ":"")+money(r.price_from);return range+(r.unit?" / "+r.unit:"");}

function extend(files,rows,origin,staging=false){if(origin!==(staging?"https://staging.invalid":"https://leogo.co.ke"))throw Error("Invalid origin");rows=normalize(rows);const root="/seo-catalogue/business/",path=r=>root+r.kind+"/"+r.id+"/",section=k=>root+k+"/",script=staging?"":'<script src="/seo-catalogue/business/live.js" defer></script>',nav='<a href="'+root+'">Services &amp; businesses</a>';for(const [p,s] of Object.entries(files))if(p.startsWith("seo-catalogue/")&&p.endsWith(".html"))files[p]=s.replace('<div class="navlinks">','<div class="navlinks">'+nav);const page=(title,url,body,desc)=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | LEOGO Digital Market</title><meta name="description" content="${esc(desc.slice(0,250))}"><link rel="canonical" href="${esc(origin+url)}">${staging?'<meta name="robots" content="noindex,nofollow">':'<link rel="icon" href="/assets/images/leogo-official-logo.jpg">'}<link rel="stylesheet" href="/seo-catalogue/catalogue.css"></head><body><header><nav class="nav"><a class="brand" href="${staging?"/seo-catalogue/":"/"}">${staging?"":'<img src="/assets/images/leogo-official-logo.jpg" alt="LEOGO logo">'}<span>LEOGO DIGITAL MARKET<small>Everything You Need. Delivered.</small></span></a><div class="navlinks"><a href="/seo-catalogue/">Products</a>${nav}</div></nav></header><main>${body}</main><footer>LEOGO DIGITAL MARKET · ${staging?"Staging preview":"Everything you need. Delivered."}</footer>${script}</body></html>\n`;const put=(url,html)=>files[url.slice(1)+"index.html"]=html;const hero=(title,desc)=>'<section class="hero"><span class="eyebrow">Explore LEOGO</span><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></section>';const photo=r=>{const u=image(r,staging);return u?'<img src="'+esc(u)+'" alt="'+esc(r.title)+'" loading="lazy" decoding="async" width="480" height="480">':'<span>Photo not available</span>';};const cards=rs=>'<div class="grid">'+rs.map(r=>'<article class="card" data-business-card="'+r.kind+'/'+r.id+'"><a class="photo" href="'+path(r)+'">'+photo(r)+'</a><div class="cardbody"><span class="tag">'+esc(GROUPS[r.kind].name)+'</span><h2><a href="'+path(r)+'">'+esc(r.title)+'</a></h2><span class="muted">'+esc(r.location)+'</span><span class="price" data-business-price>Check current price</span><a class="btn" href="'+path(r)+'">View details</a></div></article>').join("")+'</div>';put(root,page("Services & businesses",root,hero("Services & businesses","Explore LEOGO services, stays, transport, property listings and seller storefronts.")+'<div class="grid">'+Object.entries(GROUPS).map(([k,g])=>'<article class="card"><a class="category-visual" href="'+section(k)+'" aria-label="'+esc(g.name)+'"><img src="'+root+'art/'+k+'.svg" alt="" width="600" height="320" loading="lazy" decoding="async"></a><div class="cardbody"><span class="tag">LEOGO</span><h2><a href="'+section(k)+'">'+esc(g.name)+'</a></h2><p>'+esc(g.intro)+'</p><span class="muted">'+rows.filter(r=>r.kind===k).length+' current listings</span><a class="btn" href="'+section(k)+'">Explore</a></div></article>').join("")+'</div>',"Explore LEOGO services, accommodation, transport, properties and sellers."));for(const [k,g] of Object.entries(GROUPS)){const rs=rows.filter(r=>r.kind===k);put(section(k),page(g.name,section(k),'<p class="crumb"><a href="'+root+'">Services &amp; businesses</a> / '+esc(g.name)+'</p>'+hero(g.name,g.intro)+(rs.length?cards(rs):'<p class="notice">No eligible individual listings are currently published in this section. Check the LEOGO customer marketplace for updates.</p>')+(staging?"":'<p><a class="btn" href="/#'+g.anchor+'">'+esc(g.cta)+'</a></p>'),g.intro));}for(const r of rows){const g=GROUPS[r.kind];const body='<p class="crumb"><a href="'+root+'">Services &amp; businesses</a> / <a href="'+section(r.kind)+'">'+esc(g.name)+'</a></p><article class="detail" data-business-id="'+r.kind+'/'+r.id+'"><div class="photo">'+photo(r)+'</div><div><span class="tag">'+esc(g.name)+'</span><h1>'+esc(r.title)+'</h1><p class="muted">'+esc(r.location)+'</p><p class="desc" id="business-description">'+esc(r.description)+'</p><p class="price" id="business-price" role="status">Check current price and availability</p>'+(staging?"":'<p><a class="btn" id="business-action" hidden href="'+esc(action(r))+'">'+esc(g.cta)+'</a></p>')+'<p class="notice">Confirm availability, prices and any booking, viewing or delivery conditions in the existing LEOGO customer marketplace.</p></div></article>';put(path(r),page(r.title,path(r),body,r.description||g.intro));}for(const k of Object.keys(GROUPS))files['seo-catalogue/business/art/'+k+'.svg']=categoryArt(k);if(files['seo-catalogue/catalogue.css'])files['seo-catalogue/catalogue.css']+='\n.category-visual{display:block;aspect-ratio:15/8;overflow:hidden;background:#eaf0f8;border-bottom:1px solid #e1e6ee}.category-visual img{width:100%;height:100%;display:block;object-fit:cover;transition:transform .2s ease}.card:hover .category-visual img{transform:scale(1.035)}.cardbody p{line-height:1.5;margin:4px 0 8px}@media(prefers-reduced-motion:reduce){.category-visual img{transition:none}}\n';const urls=[root,...Object.keys(GROUPS).map(section),...rows.map(path)];if(!files["sitemap.xml"]?.includes("</urlset>"))throw Error("Missing product sitemap");files["sitemap.xml"]=files["sitemap.xml"].replace("</urlset>",urls.map(p=>"  <url><loc>"+esc(origin+p)+"</loc></url>").join("\n")+"\n</urlset>");return files;}

function browser(key){const cards=[...document.querySelectorAll("[data-business-card]")],detail=document.querySelector("[data-business-id]"),status=document.getElementById("business-price"),link=document.getElementById("business-action");if(!cards.length&&!detail)return;fetch("https://dzdciuqkqixwutvtfotj.supabase.co/rest/v1/rpc/seo_public_business_v1",{method:"POST",headers:{apikey:key,"Content-Type":"application/json"},body:"{}",cache:"no-store"}).then(r=>{if(!r.ok)throw Error("unavailable");return r.json()}).then(rows=>{const map=new Map(normalize(rows).map(r=>[r.kind+"/"+r.id,r]));for(const card of cards){const r=map.get(card.dataset.businessCard);if(!r){card.hidden=true;continue;}card.querySelector("[data-business-price]").textContent=price(r);}if(!detail||!status||!link)return;const r=map.get(detail.dataset.businessId);if(!r){status.textContent="This listing is no longer available.";detail.querySelectorAll("a").forEach(a=>a.hidden=true);const h=detail.querySelector("h1");if(h)h.textContent="Listing unavailable";const desc=document.getElementById("business-description");if(desc)desc.textContent="";const img=detail.querySelector(".photo");if(img)img.hidden=true;const m=document.createElement("meta");m.name="robots";m.content="noindex";document.head.append(m);return;}status.textContent=price(r);const desc=document.getElementById("business-description");if(desc)desc.textContent=r.description;link.href=action(r);link.hidden=false;}).catch(()=>{if(status)status.textContent="Live availability unavailable. Visit the LEOGO marketplace to check current listings.";});}

function liveSource(key){if(!/^sb_publishable_[A-Za-z0-9_-]+$/.test(key))throw Error("Public key required");return "const GROUPS="+JSON.stringify(GROUPS)+";\n"+[publicText,uuid,normalize,action,price].map(f=>f.toString()).join("\n")+"\n("+browser.toString()+")("+JSON.stringify(key)+");\n";}
export {extend,liveSource,normalize,image,price,action};
